def seed():
    """Insert missing demo tickets/replies without touching user-created records."""
    with SessionLocal() as db:
        existing_numbers = set(db.scalars(select(Ticket.ticket_number)).all())
        tickets_by_number = {}
        for index, row in enumerate(SEED, 1):
            ticket_number = f"SP-{1000 + index}"
            if ticket_number not in existing_numbers:
                name, email, subject, description, priority, category, status = row
                ticket = Ticket(ticket_number=ticket_number, customer_name=name, customer_email=email,
                    subject=subject, description=description, priority=priority, category=category,
                    status=status, sentiment="negative" if priority in ("high", "urgent") else "neutral")
                db.add(ticket)
                tickets_by_number[ticket_number] = ticket
            else:
                tickets_by_number[ticket_number] = db.scalar(select(Ticket).where(Ticket.ticket_number == ticket_number))
        for index, row in enumerate(EXTRA_SEED, 33):
            ticket_number = f"SP-{1000 + index}"
            if ticket_number not in existing_numbers:
                name, email, subject, description, priority, category, status = row
                ticket = Ticket(ticket_number=ticket_number, customer_name=name, customer_email=email,
                    subject=subject, description=description, priority=priority, category=category,
                    status=status, sentiment="negative" if priority in ("high", "urgent") else "neutral")
                db.add(ticket)
                tickets_by_number[ticket_number] = ticket
            else:
                tickets_by_number[ticket_number] = db.scalar(select(Ticket).where(Ticket.ticket_number == ticket_number))
        db.flush()
        for ticket_number, messages in REPLIES.items():
            ticket = tickets_by_number.get(ticket_number)
            if ticket and not db.scalar(select(TicketReply.id).where(TicketReply.ticket_id == ticket.id).limit(1)):
                for sender_type, sender_name, body in messages:
                    db.add(TicketReply(ticket_id=ticket.id, sender_type=sender_type, sender_name=sender_name, body=body))
        for ticket_number, messages in EXTRA_REPLIES.items():
            ticket = tickets_by_number.get(ticket_number)
            if ticket and not db.scalar(select(TicketReply.id).where(TicketReply.ticket_id == ticket.id).limit(1)):
                for sender_type, sender_name, body in messages:
                    db.add(TicketReply(ticket_id=ticket.id, sender_type=sender_type, sender_name=sender_name, body=body))
        db.commit()
